# Approve all pending Venmo payment requests created in this month or last month, then withdraw remaining Venmo balance to card ending in 1102.

import datetime as dt

def parse_dt(s):
    if s is None:
        return None
    if isinstance(s, (int,float)):
        return dt.datetime.fromtimestamp(s)
    s = str(s)
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    return dt.datetime.fromisoformat(s)

# Ensure required variables exist
if 'venmo_token' not in globals() or not venmo_token:
    venmo_login = apis.venmo.login(username='timothy.whit@gmail.com', password='PK5hS=R')
    venmo_token = venmo_login.get('access_token')

if 'last_month_start' not in globals() or 'next_month_start' not in globals():
    now = dt.datetime.now()
    if now.month == 1:
        last_month_start = dt.datetime(now.year-1, 12, 1)
    else:
        last_month_start = dt.datetime(now.year, now.month-1, 1)
    if now.month == 12:
        next_month_start = dt.datetime(now.year+1, 1, 1)
    else:
        next_month_start = dt.datetime(now.year, now.month+1, 1)

# Card ending in 1102 -> payment_card_id
# Use existing cards/last4 if present; otherwise fetch.
if 'cards' not in globals():
    cards = apis.venmo.show_payment_cards(access_token=venmo_token)

card_target_last4 = '1102'
card_candidates = []
for c in cards:
    num = c.get('card_number')
    if num is None:
        continue
    int_num = int(round(float(num)))
    s = str(int_num)
    lf = s[-4:] if len(s)>=4 else s
    if lf == card_target_last4:
        card_candidates.append((c.get('payment_card_id'), c.get('card_name'), lf))

print('card_candidates_ending_1102', card_candidates)
if not card_candidates:
    raise RuntimeError('No payment card ending in 1102 found')
payment_card_id_target = card_candidates[0][0]

# Fetch pending requests if not already present
if 'pending_requests' not in globals():
    pending_requests = []
    page_index = 0
    page_limit = 20
    while True:
        page = apis.venmo.show_received_payment_requests(access_token=venmo_token, status='pending', page_index=page_index, page_limit=page_limit)
        if not page:
            break
        pending_requests.extend(page)
        page_index += 1
        if len(page) < page_limit:
            break

selected = []
for r in pending_requests:
    created_at = parse_dt(r.get('created_at'))
    if created_at is None:
        continue
    if last_month_start <= created_at < next_month_start:
        selected.append(r)

selected_ids = [r.get('payment_request_id') for r in selected]
print('selected_pending_requests_count', len(selected_ids))
print('selected_pending_requests_ids', selected_ids)

# Approve each selected pending request
approve_results = []
for rid in selected_ids:
    res = apis.venmo.approve_payment_request(payment_request_id=int(rid), access_token=venmo_token)
    approve_results.append({'payment_request_id': rid, 'result': res})

success_msgs = [r for r in approve_results if isinstance(r.get('result'), dict) and 'message' in r['result']]
print('approved_count', len(success_msgs))
print('approve_first_3', approve_results[:3])

# Withdraw remaining Venmo balance if any
balance_resp = apis.venmo.show_venmo_balance(access_token=venmo_token)
venmo_balance = balance_resp.get('venmo_balance')
print('venmo_balance_after_approvals', venmo_balance)

withdraw_resp = None
if venmo_balance is not None:
    try:
        venmo_balance_val = float(venmo_balance)
    except Exception:
        venmo_balance_val = None
    if venmo_balance_val is not None and venmo_balance_val > 0.0:
        withdraw_resp = apis.venmo.withdraw_from_venmo_balance(amount=venmo_balance_val, payment_card_id=int(payment_card_id_target), access_token=venmo_token)
        print('withdraw_resp', withdraw_resp)
    else:
        print('no_withdraw_needed')
else:
    print('could_not_determine_balance')
